GW_Init:                                    // Route113_GlassWorkshop_OnTransition
    h_setflag FLAG_LANDMARK_GLASS_WORKSHOP
    h_goto_if_ne VAR_GLASS_WORKSHOP_STATE, 1, L_GW_InitDone
    h_setvar VAR_GLASS_WORKSHOP_STATE, 2
L_GW_InitDone:
